&НаСервере
Процедура ПриСозданииНаСервере(Отказ, СтандартнаяОбработка)

	ЭтаФорма.Заголовок = НСтр("ru='Описание вида операции ""';uk='Опис виду операції ""'") + Строка(Параметры.ВидОперации)+"""";

