	ИначеЕсли ИмяСобытия = "ВыборРеквизитовПолучателя" Тогда
		ЗаполнитьЗначенияСвойств(Объект, Параметр);
		НадписьРеквизитыПолучателя = УстановитьНадписьРеквизитыПолучателя(ЭтаФорма);
