	ОтборДата = ОбщегоНазначенияБП.ПолучитьРабочуюДату();

	Если НЕ ЗначениеЗаполнено(ОтборБанковскийСчет) Тогда
		УчетДенежныхСредствБП.УстановитьБанковскийСчет(
			ОтборБанковскийСчет, 
