	КонецЕсли;
	Если ПоляОбъекта.Свойство("УчетСуммНУ") Тогда
		Объект[ПоляОбъекта["УчетСуммНУ"] + "Доступность"] = ДанныеСчета.УчетСуммНУ;
	КонецЕсли;

