			ПозицияСловаПредставления = Найти(ТекстЗапросаВРег, "ПРЕДСТАВЛЕНИЯ_");

			ЭтоОписаниеПредставления = Ложь;

			Если ПозицияСловаПредставления > 0 
				И ПозицияСловаПредставления > ПозицияСловаПоместить Тогда

