// СЛУЖЕБНЫЕ ПРОЦЕДУРЫ И ФУНКЦИИ

Процедура УстановитьПояснениеКНомеруЛицевогоСчета(Форма, СтруктураПояснения = Неопределено) Экспорт

	Если СтруктураПояснения = Неопределено Тогда
		СообщенияПроверки = НСтр("ru='';uk=''");
		ТекстНадписи  = "";
		ЭлементЦветТекста = Форма.ЦветСтиляЦветТекстаПоля;
		Картинка = Новый Картинка;
	Иначе
		СообщенияПроверки = СтруктураПояснения.СообщенияПроверки;
		ТекстНадписи = СтруктураПояснения.ТекстНадписи;
		ЭлементЦветТекста = СтруктураПояснения.ЭлементЦветТекста;
		Картинка = СтруктураПояснения.Картинка;
	КонецЕсли;

	Форма.ФизическоеЛицоЛСКартинка = Картинка;
	Форма.ФизическоеЛицоЛСНадпись  = ТекстНадписи;

	ОбщегоНазначенияКлиентСервер.УстановитьСвойствоЭлементаФормы(
		Форма.Элементы, "ФизическоеЛицоЛСНадпись", "Подсказка", СообщенияПроверки);
	ОбщегоНазначенияКлиентСервер.УстановитьСвойствоЭлементаФормы(
		Форма.Элементы, "ФизическоеЛицоЛСНадпись", "ЦветТекста", ЭлементЦветТекста);
	ОбщегоНазначенияКлиентСервер.УстановитьСвойствоЭлементаФормы(
		Форма.Элементы, "ЛицевыеСчетаСотрудниковПоЗарплатнымПроектамНомерЛицевогоСчета", "Подсказка", СообщенияПроверки);
	ОбщегоНазначенияКлиентСервер.УстановитьСвойствоЭлементаФормы(
		Форма.Элементы, "ЛицевыеСчетаСотрудниковПоЗарплатнымПроектамНомерЛицевогоСчета", "ЦветТекста", ЭлементЦветТекста);

КонецПроцедуры

