	НачатьТранзакцию();
	Попытка
		НовыйУзел = ПланыОбмена.МиграцияПриложений.СоздатьУзел();
		НовыйУзел.Наименование = СтрШаблон(НСтр("ru='Миграция в %1 (%2)';uk='Міграція в %1 (%2)'"), Метаданные.Представление(), АдресПриложения);
