// Возвращает режим исполнения внешнего модуля в модели сервиса.
//
// Параметры:
//  ВнешнийМодуль - ЛюбаяСсылка,
//
// Возвращаемое значение - Строка - режим исполнения внешнего модуля.
//
Функция РежимИсполненияВнешнегоМодуля(Знач ВнешнийМодуль) Экспорт

	Если ОбщегоНазначенияПовтИсп.РазделениеВключено() Тогда

		Ключ = КлючРегистраПоСсылке(ВнешнийМодуль);

		Если ОбщегоНазначенияПовтИсп.ДоступноИспользованиеРазделенныхДанных() Тогда

			Режим = РегистрыСведений.РежимыПодключенияВнешнихМодулейОбластейДанных.РежимИсполненияВнешнегоМодуля(
				Ключ.Тип, Ключ.Идентификатор);

			Если Режим = Неопределено Тогда

				Режим = РегистрыСведений.РежимыПодключенияВнешнихМодулейВМоделиСервиса.РежимИсполненияВнешнегоМодуля(
					Ключ.Тип, Ключ.Идентификатор);

				Возврат Режим;

			Иначе

				Возврат Режим;

			КонецЕсли;

		Иначе

			Режим = РегистрыСведений.РежимыПодключенияВнешнихМодулейВМоделиСервиса.РежимИсполненияВнешнегоМодуля(
				Ключ.Тип, Ключ.Идентификатор);

			Возврат Режим;

		КонецЕсли;

	Иначе
		ВызватьИсключение НСтр("ru='Функция не предназначена для вызова в информационной базе, в которой вык

лючено разделение по областям данных!';uk='Функція не призначена для виклику в інформаційній базі, в якій вимкнено поділ по областях даних!'");
