//
// Возвращаемое значение:
//  Булево, есть ли право на налоговый кредит
Функция ЕстьПравоНаНалоговыйКредит(НалоговоеНазначение) Экспорт

	// Право на налоговый кредит дается только, если
	//		приобретаемые ценности будут использоваться в хозяйственной деятельности
	//			в облагаемых НДС операциях
	Если Не ТипЗнч(НалоговоеНазначение) = Тип("СправочникСсылка.НалоговыеНазначенияАктивовИЗатрат") ИЛИ
		 (НалоговоеНазначение.ВидНалоговойДеятельности = Справочники.ВидыНалоговойДеятельности.НеОблагаемая) ИЛИ
		 (НалоговоеНазначение.ВидДеятельностиНДС = Перечисления.ВидыДеятельностиНДС.Необлагаемая) Тогда
		Возврат Ложь;
	КонецЕсли;

	Возврат Истина;

